// ============================================================================
// FAO HITL Gateway v1 — Payload Validation
// ----------------------------------------------------------------------------
// FAO-GOV-004: Validates payload before inserting into hitl_queue.
// Mirrors the Writer's pattern: structural correctness only, not semantic
// quality. Rationale quality is the policy engine's responsibility.
//
// Required NOT NULL fields per hitl_queue (Migration 0005):
//   correlation_id, agent_id, agent_invoker_email, risk_tier,
//   policy_sub_tier, policy_rationale
//
// Threaded through (used by Slack message + Writer event, not validated):
//   execution_id, escalated_assets, execution_summary
//
// ai_human_brief is intentionally absent — wired when Claude advisory
// lands (Apr 25 mid-day). SQL hardcodes NULL until then.
// ============================================================================

const input = $input.first().json;

const required = [
  'correlation_id',
  'execution_id',
  'agent_id',
  'agent_invoker_email',
  'risk_tier',
  'policy_sub_tier',
  'policy_rationale'
];

const missing = required.filter(f => input[f] === undefined || input[f] === null || input[f] === '');
if (missing.length > 0) {
  throw new Error(`FAO-GOV-004 hitl_gateway: missing required field(s): ${missing.join(', ')}`);
}

// risk_tier — same enum as shadow_ledger
const validRiskTiers = ['GREEN', 'AMBER', 'RED'];
if (!validRiskTiers.includes(input.risk_tier)) {
  throw new Error(`FAO-GOV-004 hitl_gateway: invalid risk_tier '${input.risk_tier}'. Must be one of: ${validRiskTiers.join(', ')}`);
}

// policy_sub_tier — required for HITL (only STANDARD/CRITICAL valid here;
// nullable in shadow_ledger but NOT NULL in hitl_queue with default STANDARD)
const validSubTiers = ['STANDARD', 'CRITICAL'];
if (!validSubTiers.includes(input.policy_sub_tier)) {
  throw new Error(`FAO-GOV-004 hitl_gateway: invalid policy_sub_tier '${input.policy_sub_tier}'. Must be one of: ${validSubTiers.join(', ')}`);
}

// UUID format
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidPattern.test(input.correlation_id)) {
  throw new Error(`FAO-GOV-004 hitl_gateway: correlation_id is not a valid UUID: '${input.correlation_id}'`);
}
if (!uuidPattern.test(input.execution_id)) {
  throw new Error(`FAO-GOV-004 hitl_gateway: execution_id is not a valid UUID: '${input.execution_id}'`);
}

// Email format — defensive check before SQL
const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailPattern.test(input.agent_invoker_email)) {
  throw new Error(`FAO-GOV-004 hitl_gateway: agent_invoker_email is not a valid email: '${input.agent_invoker_email}'`);
}

// agent_id format — alphanumeric + underscore only (matches all seeded agents)
if (!/^[a-z0-9_]+$/i.test(input.agent_id)) {
  throw new Error(`FAO-GOV-004 hitl_gateway: agent_id contains unexpected characters: '${input.agent_id}'`);
}

// Defensive sanitization of policy_rationale: prevent breakout from
// dollar-quoted SQL string. We use $rationale$...$rationale$ delimiters
// downstream; reject any rationale that contains the closing delimiter.
// Belt-and-suspenders — policy engine doesn't produce these strings.
if (typeof input.policy_rationale !== 'string' || input.policy_rationale.includes('$rationale$')) {
  throw new Error(`FAO-GOV-004 hitl_gateway: policy_rationale contains reserved sequence or is not a string`);
}

return [{ json: {
  correlation_id:       input.correlation_id,
  execution_id:         input.execution_id,
  agent_id:             input.agent_id,
  agent_invoker_email:  input.agent_invoker_email,
  risk_tier:            input.risk_tier,
  policy_sub_tier:      input.policy_sub_tier,
  policy_rationale:     input.policy_rationale,
  escalated_assets:     Array.isArray(input.escalated_assets) ? input.escalated_assets : [],
  execution_summary:    input.execution_summary ?? null
}}];

// ============================================================================
// FAO HITL Gateway v1 — Validate Insert + Compose Notification Context
// ----------------------------------------------------------------------------
// (UPDATED Apr 25 v3 — APPROVAL_BASE_URL now points at /fao-hitl-confirm
//  per Approval Handler v2's GET/POST split. GET is now read-only
//  confirmation page; the form on that page POSTs to /fao-hitl-resolve.)
//
// Empirical motivation: Slack's link-expander GETs every URL in a posted
// message within ~2-3 seconds. v1's GET endpoint mutated state, so the
// expander auto-resolved every HITL. Apr 25 evening flagship run produced
// 6 approval_handler executions within 3 seconds of the Slack message —
// before the human approver could see the message, let alone click.
//
// HTTP semantics restored: GET is safe (shows confirmation page),
// POST is the mutating action (form submission only).
// ============================================================================

const APPROVAL_BASE_URL = 'https://n8n.velocyt.ca/webhook/fao-hitl-confirm';

const approvers = [
  { email: 'sarah.chen@finagent-os.demo',     name: 'Sarah Chen',     role: 'Controller' },
  { email: 'marcus.patel@finagent-os.demo',   name: 'Marcus Patel',   role: 'CFO' },
  { email: 'aisha.okonkwo@finagent-os.demo',  name: 'Aisha Okonkwo',  role: 'FP&A Lead' }
];

const inserted = $input.all();

if (inserted.length === 0 || !inserted[0].json || !inserted[0].json.hitl_id) {
  const ctx = $('Validate Payload').first().json;
  throw new Error(
    `FAO-GOV-004 hitl_gateway: Insert HITL Row returned zero rows unexpectedly. ` +
    `fao_hitl_create() should have raised before reaching this node. ` +
    `Inputs: agent_invoker_email='${ctx.agent_invoker_email}', agent_id='${ctx.agent_id}'.`
  );
}

const ctx = $('Validate Payload').first().json;
const row = inserted[0].json;

const approver_links = approvers.map(a => {
  const approve_url = `${APPROVAL_BASE_URL}?hitl_id=${row.hitl_id}&decision=APPROVED&approver_email=${encodeURIComponent(a.email)}`;
  const reject_url  = `${APPROVAL_BASE_URL}?hitl_id=${row.hitl_id}&decision=REJECTED&approver_email=${encodeURIComponent(a.email)}`;
  return { ...a, approve_url, reject_url };
});

const tier_emoji = ctx.policy_sub_tier === 'CRITICAL' ? ':rotating_light:' : ':warning:';
const escalated_summary = (ctx.escalated_assets && ctx.escalated_assets.length > 0)
  ? ctx.escalated_assets.join(', ')
  : '(none — review rationale)';

const approve_lines = approver_links.map(a =>
  `:white_check_mark: <${a.approve_url}|*Approve as ${a.name}*> _(${a.role})_`
).join('\n');

const reject_lines = approver_links.map(a =>
  `:x: <${a.reject_url}|*Reject as ${a.name}*> _(${a.role})_`
).join('\n');

const slack_text = [
  `${tier_emoji} *HITL Approval Required — ${ctx.agent_id}* (${ctx.policy_sub_tier})`,
  ``,
  `*Correlation ID:* \`${ctx.correlation_id}\``,
  `*Execution ID:* \`${ctx.execution_id}\``,
  `*Risk Tier:* ${ctx.risk_tier}`,
  `*Invoker:* ${ctx.agent_invoker_email}`,
  `*HITL ID:* ${row.hitl_id}`,
  `*SLA timeout:* ${new Date(row.timeout_at).toISOString()}`,
  ``,
  `*Rationale:*`,
  `> ${ctx.policy_rationale}`,
  ``,
  `*Escalated assets:* ${escalated_summary}`,
  ``,
  `*Approve:*`,
  approve_lines,
  ``,
  `*Reject:*`,
  reject_lines,
  ``,
  `_Each link opens a confirmation page. The decision is recorded only when you click *Confirm* on that page (form POST). Slack's link-expander cannot trigger resolution._`,
  `_FAO-GOV-004: An approver cannot resolve their own invocation. Self-approval attempts raise a loud database exception at the hitl_queue_sod_guard trigger._`
].join('\n');

return [{ json: {
  ...ctx,
  hitl_id:           row.hitl_id,
  agent_invoker_id:  row.agent_invoker_id,
  timeout_at:        row.timeout_at,
  created_at:        row.created_at,
  approver_links,
  slack_text
}}];

// ============================================================================
// FAO HITL Gateway v1 — Compose HITL_REQUESTED Writer Payload
// ----------------------------------------------------------------------------
// Threads the same correlation_id and execution_id used by the parent
// agent's STARTED/ASSET_RECONCILED rows. The shadow_ledger HITL_REQUESTED
// row is the audit-trail record that the gateway successfully created
// the hitl_queue request and notified the approver.
//
// policy_outcome stays REQUIRE_HUMAN — we are logging the fact of the
// request, not changing the upstream decision. status is SUCCESS because
// the gateway operation itself succeeded (request created + notified).
//
// hitl_status is PENDING — this row records that approval is awaited.
// The matching HITL_RESOLVED row will be written by the Approval Handler
// workflow when the approver decides.
// ============================================================================

const ctx = $('Validate Insert + Compose').first().json;

return [{ json: {
  correlation_id:      ctx.correlation_id,
  execution_id:        ctx.execution_id,
  agent_id:            ctx.agent_id,
  risk_tier:           ctx.risk_tier,
  inputs: {
    event_type:           'HITL_REQUESTED',
    hitl_id:              ctx.hitl_id,
    agent_invoker_id:     ctx.agent_invoker_id,
    agent_invoker_email:  ctx.agent_invoker_email,
    timeout_at:           ctx.timeout_at,
    sub_tier:             ctx.policy_sub_tier,
    notification_channel: 'slack',
    approve_url:          ctx.approve_url,
    reject_url:           ctx.reject_url,
    escalated_assets:     ctx.escalated_assets
  },
  ai_prompt:           null,
  ai_output:           null,
  ai_confidence:       null,
  fractional_cost_usd: null,
  policy_outcome:      'REQUIRE_HUMAN',
  policy_sub_tier:     ctx.policy_sub_tier,
  policy_rationale:    `FAO-GOV-004 HITL request created (hitl_id=${ctx.hitl_id}, sub_tier=${ctx.policy_sub_tier}). Awaiting approval. Notification dispatched to Slack #fao-approvals. SLA timeout: ${ctx.timeout_at}. Underlying execution rationale: ${ctx.policy_rationale}`,
  obligations:         [],
  hitl_status:         'PENDING',
  hitl_approver_id:    null,
  status:              'SUCCESS',
  error_details:       null
}}];
